import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync, mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { tmpdir } from 'node:os';

test('the gate is wired into the pre-commit hook', () => {
  assert.match(readFileSync('.githooks/pre-commit', 'utf8'), /enforce-quality\.sh/u);
});

test('the gate runs and reports its own exit status', () => {
  // Exercised rather than read: a gate nobody executes is a gate nobody has.
  const run = () => execFileSync('bash', ['scripts/enforce-quality.sh'], { stdio: 'pipe' });
  assert.doesNotThrow(run);
});

const GATE_SCRIPT = resolve('scripts/enforce-quality.sh');

function makeRepo() {
  const dir = mkdtempSync(join(tmpdir(), 'quality-gate-'));
  execFileSync('git', ['init', '-q'], { cwd: dir });
  return dir;
}

function stage(dir, relPath, content) {
  const filePath = join(dir, relPath);
  mkdirSync(dirname(filePath), { recursive: true });
  writeFileSync(filePath, content);
  execFileSync('git', ['add', relPath], { cwd: dir });
}

function commit(dir, message) {
  execFileSync(
    'git',
    ['-c', 'user.email=test@example.com', '-c', 'user.name=Test', 'commit', '-q', '-m', message],
    { cwd: dir },
  );
}

function runGate(dir, env = {}) {
  try {
    const stdout = execFileSync('bash', [GATE_SCRIPT], {
      cwd: dir,
      env: { ...process.env, ...env },
    });
    return { status: 0, stdout: stdout.toString(), stderr: '' };
  } catch (err) {
    return { status: err.status, stdout: err.stdout?.toString() ?? '', stderr: err.stderr?.toString() ?? '' };
  }
}

test('blocks a staged debugger statement', () => {
  const dir = makeRepo();
  stage(dir, 'app.js', 'function f() {\n  debugger;\n  return 1;\n}\n');
  const result = runGate(dir);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /BLOCK.*debugger/u);
});

test('blocks a staged pdb.set_trace() call', () => {
  const dir = makeRepo();
  stage(dir, 'app.py', 'def f():\n    pdb.set_trace()\n    return 1\n');
  const result = runGate(dir);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /BLOCK.*pdb\.set_trace/u);
});

test('blocks a staged import pdb', () => {
  const dir = makeRepo();
  stage(dir, 'app.py', 'import pdb\n\ndef f():\n    return 1\n');
  const result = runGate(dir);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /BLOCK.*import pdb/u);
});

test('blocks a staged binding.pry', () => {
  const dir = makeRepo();
  stage(dir, 'app.rb', "def f\n  binding.pry\n  1\nend\n");
  const result = runGate(dir);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /BLOCK.*binding\.pry/u);
});

test('blocks staged merge-conflict markers', () => {
  const dir = makeRepo();
  const conflicted = '<<<<<<< HEAD\nfoo\n=======\nbar\n>>>>>>> feature\n';
  stage(dir, 'app.txt', conflicted);
  const result = runGate(dir);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /BLOCK.*<<<<<<< HEAD/u);
});

test('EOS_BYPASS_CLEANUP=1 overrides a hard block', () => {
  const dir = makeRepo();
  stage(dir, 'app.js', 'debugger;\n');
  const result = runGate(dir, { EOS_BYPASS_CLEANUP: '1' });
  assert.equal(result.status, 0);
});

test('warns but does not block a staged console.log', () => {
  const dir = makeRepo();
  stage(dir, 'app.js', 'console.log("hi");\n');
  const result = runGate(dir);
  assert.equal(result.status, 0);
  assert.match(result.stderr, /WARN.*console\.log/u);
});

test('warns but does not block a staged print call', () => {
  const dir = makeRepo();
  stage(dir, 'app.py', 'print("hi")\n');
  const result = runGate(dir);
  assert.equal(result.status, 0);
  assert.match(result.stderr, /WARN.*print/u);
});

test('allows a clean staged diff with no output', () => {
  const dir = makeRepo();
  stage(dir, 'app.js', 'function add(a, b) {\n  return a + b;\n}\n');
  const result = runGate(dir);
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
});

test('does not block a diff that only removes a debugger statement', () => {
  const dir = makeRepo();
  stage(dir, 'app.js', 'debugger;\nreturn 1;\n');
  commit(dir, 'init with debugger');
  stage(dir, 'app.js', 'return 1;\n');
  const result = runGate(dir);
  assert.equal(result.status, 0, result.stderr);
});

